def icon(name, size=18, cls="ea-ico", stroke_width=2):
    """Return an inline SVG for `name`, or an empty string if unknown."""
    inner = ICONS.get(name)

    if inner is None:
        return ""

    return (
        f'<svg class="{cls}" xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="{stroke_width}" '
        f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{inner}</svg>'
    )
